import { isPrimaryKeyByCryptoName, primaryKeyToPublicKeyForCrypto } from "./lib/crypto/Cryptos.js";
import { cryptoNames, isCryptoIndex, parseCryptoIndex } from "./lib/crypto/CryptoNames.js";
import { fingerprintStartsWith, fromFingerprintDisplay, isFingerprint, publicKeyToFingerprint } from "./Fingerprint.js";
import isString from "./lib/utils/isString.js";
import last from "./lib/utils/last.js";
export { publicKeyToPrimaryKey } from "./lib/crypto/Cryptos.js";
export const isPrimaryKey = (value) => {
    if (isString(value) === false)
        return false;
    try {
        const cryptoName = readCryptoNameFromPrimaryKey(value);
        return isPrimaryKeyByCryptoName(cryptoName, value);
    }
    catch {
        return false;
    }
};
export const readCryptoIndexFromPrimaryKey = (primaryKey) => {
    return parseCryptoIndex(last(primaryKey));
};
export const readCryptoNameFromPrimaryKey = (primaryKey) => {
    const index = readCryptoIndexFromPrimaryKey(primaryKey);
    const name = cryptoNames[index];
    if (isPrimaryKeyByCryptoName(name, primaryKey) === false) {
        throw new Error("Invalid PrimaryKey");
    }
    return name;
};
export const removeCryptoIndexFromPrimaryKey = (primaryKey) => {
    const index = readCryptoIndexFromPrimaryKey(primaryKey);
    if (isCryptoIndex(index) === false) {
        throw new Error("Invalid CryptoIndex in PrimaryKey");
    }
    return primaryKey.slice(0, -1);
};
export const primaryKeyToPublicKey = (primaryKey) => {
    if (isPrimaryKey(primaryKey) === false) {
        throw new Error("Invalid PrimaryKey");
    }
    const cryptoName = readCryptoNameFromPrimaryKey(primaryKey);
    return primaryKeyToPublicKeyForCrypto(cryptoName, primaryKey);
};
export const primaryKeyToFingerprint = async (primaryKey) => {
    const publicKey = primaryKeyToPublicKey(primaryKey);
    return await publicKeyToFingerprint(publicKey);
};
export const fingerprintDisplayBelongsToPrimaryKey = async (primaryKey, fingerprintDisplay) => {
    const fingerprint = fromFingerprintDisplay(fingerprintDisplay);
    return await fingerprintBelongsToPrimaryKey(primaryKey, fingerprint);
};
export const fingerprintBelongsToPrimaryKey = async (primaryKey, fingerprint) => {
    if (!isFingerprint(fingerprint)) {
        throw new Error("Invalid Fingerprint");
    }
    const primaryKeyFingerprint = await primaryKeyToFingerprint(primaryKey);
    return fingerprintStartsWith(primaryKeyFingerprint, fingerprint);
};
